#!/usr/bin/env python3
"""Generate benchmark-only scalar bcrypt candidates; preserve all cost rounds."""
from pathlib import Path

out = ['''// Copyright 2010 The Go Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.
//
// Code generated by scalar_generate.py; DO NOT EDIT.
package bcryptlane

import "encoding/binary"

type boxesFirstState struct {
 s0, s1, s2, s3 [256]uint32
 p [18]uint32
}
''']


def encrypt():
    code = ['l ^= c.p[0]']
    for i in range(1, 17):
        x, y = ('l', 'r') if i % 2 else ('r', 'l')
        code.append(f'{y} ^= ((c.s0[byte({x}>>24)] + c.s1[byte({x}>>16)]) ^ c.s2[byte({x}>>8)]) + c.s3[byte({x})] ^ c.p[{i}]')
    return code + ['l, r = r ^ c.p[17], l']


for name, typ, inline in [('Regs', 'state', False), ('Inline', 'state', True),
                          ('Boxes', 'boxesFirstState', False), ('BoxesInline', 'boxesFirstState', True)]:
    out.append(f'func scalarEncrypt{name}(l, r uint32, c *{typ}) (uint32, uint32) {{')
    out.extend(encrypt())
    out.extend(['return l, r', '}'])
    for salted in (False, True):
        suffix = 'Salt' if salted else ''
        salt_arg = ', salts *[18]uint32' if salted else ''
        out.append(f'func scalarExpand{name}{suffix}(c *{typ}, words *[18]uint32{salt_arg}) {{')
        out.extend(['for i := range 18 { c.p[i] ^= words[i] }', 'var l, r uint32'])
        if salted:
            out.append('saltIndex := 0')
        for field, pairs in [('p', 9), ('s0', 128), ('s1', 128), ('s2', 128), ('s3', 128)]:
            # Multiplying a bounded pair index makes both destination bounds
            # provable; i += 2 loops need not prove that i is always even.
            out.append(f'for pair := range {pairs} {{')
            if salted:
                out.append('l ^= salts[saltIndex & 3]; r ^= salts[(saltIndex+1) & 3]; saltIndex += 2')
            if inline:
                out.extend(encrypt())
            else:
                out.append(f'l, r = scalarEncrypt{name}(l, r, c)')
            out.append(f'c.{field}[pair*2], c.{field}[pair*2+1] = l, r')
            out.append('}')
        out.append('}')
    out.append(f'func scalar{name}(password []byte, salt [16]byte, cost uint) (result [23]byte) {{')
    out.extend([
        'if cost < 4 || cost > 16 || len(password) > 72 { panic("invalid scalar experiment input") }',
        'key := append(append([]byte(nil), password...), 0)',
        'words, salts := keyWords(key), keyWords(salt[:])',
        f'c := {typ}{{p: p, s0: s0, s1: s1, s2: s2, s3: s3}}',
        f'scalarExpand{name}Salt(&c, &words, &salts)',
        f'for rounds := 0; rounds < 1<<cost; rounds++ {{ scalarExpand{name}(&c, &words); scalarExpand{name}(&c, &salts) }}',
        'text := [6]uint32{0x4f727068,0x65616e42,0x65686f6c,0x64657253,0x63727944,0x6f756274}',
        'for block := range 3 {',
        ' l, r := text[2*block], text[2*block+1]',
        f' for range 64 {{ l, r = scalarEncrypt{name}(l, r, &c) }}',
        ' text[2*block], text[2*block+1] = l, r',
        '}',
        'var raw [24]byte',
        'for i, word := range text { binary.BigEndian.PutUint32(raw[i*4:], word) }',
        'copy(result[:], raw[:23])',
        'return',
        '}',
    ])

Path(__file__).with_name('scalar_generated_test.go').write_text('\n'.join(out) + '\n')
